SELECT 
FROM biz_guide_sheet_answer

    binding_id = #{bindingId}
    AND student_id = #{studentId}
    AND lesson_id = #{lessonId}
    AND source_sheet_id = #{sourceSheetId}
    AND status = #{status}

SELECT 
FROM biz_guide_sheet_answer
WHERE student_id = #{studentId}
  AND binding_id = #{bindingId}

SELECT COALESCE(AVG(scoped_answer.total_score), 0)
FROM (
    SELECT DISTINCT a.answer_id, a.total_score
    FROM biz_guide_sheet_answer a
    INNER JOIN biz_guide_sheet_progress p
            ON p.binding_id = a.binding_id
           AND p.student_id = a.student_id
    WHERE a.binding_id = #{bindingId}
      AND p.dept_id = #{deptId}
      AND p.entry_year = #{entryYear}
      AND p.class_code = #{classCode}
      AND a.status = '2'
      AND a.total_score IS NOT NULL
) scoped_answer

mapper.insert:
INSERT INTO biz_guide_sheet_answer (
    binding_id, student_id, lesson_id, source_sheet_id, answer_json,
    current_page, status, auto_score, manual_adjustment, total_score,
    grading_status, grading_detail, draft_revision, submit_time, create_time, update_time
) VALUES (
    #{bindingId}, #{studentId}, #{lessonId}, #{sourceSheetId}, #{answerJson},
    COALESCE(#{currentPage}, 0), COALESCE(#{status}, '0'), #{autoScore},
    COALESCE(#{manualAdjustment}, 0), #{totalScore}, #{gradingStatus},
    #{gradingDetail}, COALESCE(#{draftRevision}, 0), #{submitTime}, #{createTime}, #{updateTime}
)
